// ELEMENTS:
// 1. Fundo azul iad com uma faixa azul-escura cortada a 11° à direita
// 2. Fio dourado que desce do topo
// 3. Etiqueta de preço branca, cantos retos, aro dourado no topo, a balançar presa ao fio
// 4. Rótulo "PREÇO" (label), preço 800 itálico (anim.text ou price), linha coral (sub)
// 5. CTA branco (cta) e pílula marinho com o monograma JC e o telefone (phone)
import React from "react";
import { AbsoluteFill, Img, useCurrentFrame, interpolate, spring } from "remotion";
import { loadFont } from "@remotion/google-fonts/Poppins";
import type { PrimitiveProps } from "../primitives";

loadFont("normal", { weights: ["700", "800"], subsets: ["latin", "latin-ext"] });
const { fontFamily: POPPINS } = loadFont("italic", { weights: ["800"], subsets: ["latin", "latin-ext"] });

const PRIMARY = "#05B8E6";
const DEEP = "#0A8FC0";
const INK = "#213D56";
const ACCENT = "#F06052";
const GOLD = "#CAA14D";
const MUTED = "#5B6E80";
const WHITE = "#FFFFFF";
const MONOGRAM = "data:image/webp;base64,";
const clamp = { extrapolateLeft: "clamp", extrapolateRight: "clamp" } as const;

const PrecoRevelacao: React.FC<PrimitiveProps> = ({ anim, fps, frame: box }) => {
  const f = useCurrentFrame();
  const W = box.width;
  const H = box.height;
  const p = (anim.params ?? {}) as Record<string, unknown>;
  const str = (k: string): string => (p[k] == null ? "" : String(p[k]).trim());
  const price = String(anim.text ?? "").trim() || str("price");
  const label = str("label") || "Preço";
  const sub = str("sub");
  const cta = str("cta");
  const phone = str("phone");

  // Laid out on a 540×960 stage, scaled to fit and centred.
  const u = Math.min(W / 540, H / 960);
  const ox = (W - 540 * u) / 2;
  const oy = (H - 960 * u) / 2;
  const len = Math.max(1, Math.round((anim.end - anim.start) * fps));
  const out = interpolate(f, [len - Math.round(0.35 * fps), len], [1, 0], clamp);

  const cord = interpolate(f, [0, Math.round(0.35 * fps)], [0, 1], clamp);
  // The tag drops on the cord, overshoots and settles at a slight tilt.
  const drop = spring({ frame: f - Math.round(0.2 * fps), fps, config: { damping: 7, stiffness: 90, mass: 0.8 } });
  const angle = interpolate(drop, [0, 1], [-24, -4]);
  const rise = (s: number): React.CSSProperties => {
    const k = spring({ frame: f - Math.round(s * fps), fps, config: { damping: 18, stiffness: 150 } });
    return { opacity: interpolate(k, [0, 0.4], [0, 1], clamp), transform: `translateY(${(1 - k) * 24 * u}px)` };
  };
  const priceSize = Math.min(76, 560 / Math.max(1, price.length * 0.62)) * u;

  return (
    <AbsoluteFill style={{ background: PRIMARY, overflow: "hidden", fontFamily: POPPINS, color: INK, opacity: out }}>
      <div style={{ position: "absolute", left: ox + 360 * u, top: -H, width: W, height: H * 3, background: DEEP, transform: "skewX(-11deg)" }} />
      <div style={{ position: "absolute", left: ox, top: oy, width: 540 * u, height: 960 * u }}>
        <div
          style={{
            position: "absolute",
            left: 269 * u,
            top: -oy,
            width: 2 * u,
            height: (236 * u + oy) * cord,
            background: GOLD,
          }}
        />
        <div
          style={{
            position: "absolute",
            left: 60 * u,
            top: 220 * u,
            width: 420 * u,
            display: "flex",
            flexDirection: "column",
            alignItems: "center",
            transformOrigin: "50% 0",
            opacity: interpolate(drop, [0, 0.2], [0, 1], clamp),
            transform: `translateY(${(1 - Math.min(1, drop)) * -60 * u}px) rotate(${angle}deg)`,
          }}
        >
          <div
            style={{
              width: 22 * u,
              height: 22 * u,
              borderRadius: "50%",
              background: PRIMARY,
              border: `${3 * u}px solid ${GOLD}`,
              boxSizing: "border-box",
              marginBottom: -14 * u,
              position: "relative",
              zIndex: 1,
            }}
          />
          <div
            style={{
              width: 420 * u,
              boxSizing: "border-box",
              padding: `${56 * u}px ${32 * u}px ${40 * u}px`,
              background: WHITE,
              borderTop: `${8 * u}px solid ${GOLD}`,
              boxShadow: `${10 * u}px ${10 * u}px 0 ${INK}`,
              display: "flex",
              flexDirection: "column",
              alignItems: "center",
              gap: 10 * u,
            }}
          >
            <div style={{ fontSize: 14 * u, fontWeight: 800, letterSpacing: 4 * u, color: MUTED, textTransform: "uppercase" }}>{label}</div>
            <div style={{ fontSize: priceSize, fontWeight: 800, fontStyle: "italic", lineHeight: 1, whiteSpace: "nowrap" }}>{price}</div>
            {sub ? <div style={{ fontSize: 16 * u, fontWeight: 700, color: ACCENT }}>{sub}</div> : null}
          </div>
        </div>
        {cta || phone ? (
          <div
            style={{
              position: "absolute",
              left: 0,
              right: 0,
              bottom: 120 * u,
              display: "flex",
              flexDirection: "column",
              alignItems: "center",
              gap: 14 * u,
              color: WHITE,
            }}
          >
            {cta ? <div style={{ fontSize: 22 * u, fontWeight: 800, textAlign: "center", ...rise(0.9) }}>{cta}</div> : null}
            {phone ? (
              <div
                style={{
                  display: "flex",
                  alignItems: "center",
                  gap: 12 * u,
                  padding: `${8 * u}px ${22 * u}px ${8 * u}px ${8 * u}px`,
                  background: INK,
                  borderRadius: 999,
                  ...rise(1.1),
                }}
              >
                <Img src={MONOGRAM} style={{ width: 48 * u, height: 48 * u }} />
                <div style={{ fontSize: 20 * u, fontWeight: 800, fontStyle: "italic" }}>{phone}</div>
              </div>
            ) : null}
          </div>
        ) : null}
      </div>
    </AbsoluteFill>
  );
};

export default PrecoRevelacao;
